{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C45"],
      "claim": "A comparative study in myasthenia gravis patients reported oral bioavailability of pyridostigmine, the query molecule, as 7.6%, which is below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In fasting myasthenic patients, neostigmine, a closely related quaternary ammonium dimethylcarbamate, had absolute oral bioavailability of 2.0 ± 0.33%, supporting very low oral F for this charged carbamate class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Bambuterol, a bis-dimethylcarbamate prodrug, had oral bioavailability of about 10% in healthy adults, supporting low oral F for carbamate esters with high polarity or first-pass limitations.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Rivastigmine, a tertiary-amine carbamate, had absolute oral bioavailability of 71.7% at a 6 mg dose, showing that removing the permanent quaternary charge can increase F; this is contradictory in direction but has low transferability to the permanently charged query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is pyridostigmine, a permanently charged quaternary ammonium carbamate. Direct comparative evidence gives pyridostigmine oral bioavailability of about 7.6%, and the closely related neostigmine shows 1-2% under fasting conditions, both below 20%. High-F carbamates such as rivastigmine are uncharged tertiary amines and are not sufficiently transferable to override the low-F quaternary ammonium evidence. Prediction: low.",
  "evidence_gaps": [
    "No dedicated absolute bioavailability study of pyridostigmine under fasted conditions is included; C45 is comparative and not a full absolute-F protocol.",
    "Most direct low-F evidence comes from neostigmine rather than pyridostigmine itself, though the two share the same charged carbamate pharmacophore."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

